const notes = $('Fetch Agent Notes').first().json;
const telemetry = $('Fetch All Telemetry').first().json;

const noteRows = notes.rows || [];
const allRows = telemetry.rows || [];

// Aggregate PMC moves from agent notes
const moveStats = {
  retrieve: {total: 0, deterministic: 0, intelligence: 0},
  compare: {total: 0, deterministic: 0, intelligence: 0},
  classify: {total: 0, deterministic: 0, intelligence: 0},
  infer: {total: 0, deterministic: 0, intelligence: 0},
  flag: {total: 0, deterministic: 0, intelligence: 0},
  prioritize: {total: 0, deterministic: 0, intelligence: 0}
};

const agentStats = {};
let totalActions = 0;
let totalDeterministic = 0;

for (const row of noteRows) {
  const payload = typeof row.payload === 'string' ? JSON.parse(row.payload) : (row.payload || {});
  const agent = payload.agent || 'unknown';

  if (!agentStats[agent]) {
    agentStats[agent] = {heartbeats: 0, actions: 0, deterministic: 0, intelligence: 0, moves: {}};
  }
  agentStats[agent].heartbeats++;

  for (const action of (payload.actions || [])) {
    const move = action.move || 'unknown';
    const isDet = action.deterministic === true;

    totalActions++;
    if (isDet) totalDeterministic++;

    if (moveStats[move]) {
      moveStats[move].total++;
      if (isDet) moveStats[move].deterministic++;
      else moveStats[move].intelligence++;
    }

    agentStats[agent].actions++;
    if (isDet) agentStats[agent].deterministic++;
    else agentStats[agent].intelligence++;

    if (!agentStats[agent].moves[move]) agentStats[agent].moves[move] = 0;
    agentStats[agent].moves[move]++;
  }
}

// Analyze telemetry for workflow vs agent activity ratio
const workflowEvents = allRows.filter(r => r.service === 'n8n' || (r.event_type || '').includes('workflow'));
const agentEvents = allRows.filter(r => r.service === 'agent_notes' || (r.service || '').includes('cmo') || (r.service || '').includes('cto'));

// Generate optimization recommendations
const recommendations = [];

// Check if any agent has >50% deterministic actions
for (const [agent, stats] of Object.entries(agentStats)) {
  if (stats.actions > 5 && stats.deterministic / stats.actions > 0.5) {
    recommendations.push({
      type: 'migrate_to_n8n',
      agent: agent,
      reason: Math.round(100 * stats.deterministic / stats.actions) + '% of actions are deterministic',
      top_deterministic_moves: Object.entries(stats.moves)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 3)
        .map(([m, c]) => m + ' (' + c + 'x)')
    });
  }
}

// Check if retrieve is the dominant move (common pattern to migrate)
if (moveStats.retrieve.deterministic > moveStats.retrieve.intelligence * 2) {
  recommendations.push({
    type: 'retrieve_migration',
    reason: 'Most retrieve actions are deterministic -- consider moving data fetching to n8n HTTP nodes'
  });
}

// Check if classify is highly deterministic (rule-based classification should be n8n)
if (moveStats.classify.deterministic > moveStats.classify.intelligence) {
  recommendations.push({
    type: 'classify_migration',
    reason: 'Most classify actions are deterministic -- consider moving to n8n Code nodes with rule tables'
  });
}

const report = {
  week_summary: {
    total_heartbeats: noteRows.length,
    total_actions: totalActions,
    deterministic_pct: totalActions > 0 ? Math.round(100 * totalDeterministic / totalActions) : 0,
    intelligence_pct: totalActions > 0 ? Math.round(100 * (totalActions - totalDeterministic) / totalActions) : 0,
    current_split: totalActions > 0 ?
      Math.round(100 * totalDeterministic / totalActions) + '/' + Math.round(100 * (totalActions - totalDeterministic) / totalActions) + ' (det/intel)' :
      'no data'
  },
  move_breakdown: moveStats,
  agent_breakdown: agentStats,
  workflow_vs_agent: {
    workflow_events: workflowEvents.length,
    agent_events: agentEvents.length,
    total_telemetry: allRows.length
  },
  recommendations: recommendations,
  analyzed_at: new Date().toISOString()
};

return [{json: report}];
